xql_query:
// ============================================================
// Rule: LNX_External Key-Based Access
// Vendor: Linux
// Objective:
// Detect activity associated with LNX_External Key-Based Access.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0001 - Initial Access
// Technique: T1078 - Valid Accounts

// Seleciona o dataset de logs brutos do Linux
dataset = linux_linux_raw 

// Filtra apenas os logs que indicam autenticação bem-sucedida via chave pública SSH
| filter _raw_log contains "Accepted publickey for" 

// Seleciona os campos relevantes para análise: nome do host, diretório atual, comando executado, usuário e IP de origem
| fields hostname, pwd, command, username, src_ip 

// Exclui acessos feitos pelo usuário de serviço '<SERVICE_ACCOUNT_2>'
| filter (username != """<SERVICE_ACCOUNT_2>""") 

// Exclui acessos feitos pelo usuário de serviço '<SERVICE_ACCOUNT_1>'
| filter (username != """<SERVICE_ACCOUNT_1>""") 

// Remove logs que contenham conexões originadas dos IPs internos ou confiáveis especificados
| filter (
    src_ip  !=  """<INTERNAL_IP_1>""" and 
    src_ip  !=  """<INTERNAL_IP_2>""" and 
    src_ip  !=  """<INTERNAL_IP_3>""" and 
    src_ip  !=  """<INTERNAL_IP_4>""" and 
    src_ip  !=  """<INTERNAL_IP_5>""" and
    src_ip  !=  """<INTERNAL_IP_6>"""
)
